<?php
namespace App\Http\Controllers;
use App\Models\{Booking,BookingResource,BookingStaffSchedule,BusinessService,Customer,Setting,Table,User};
use App\Services\{BookingService,ReservationPayments,ReservationSchedule};
use Illuminate\Http\Request;
use Illuminate\Validation\Rule;
class BookingController extends Controller {
    public function index(Request $r,?Booking $booking=null) {
        if($booking)\Illuminate\Support\Facades\Gate::authorize('view',$booking);
        $d=$r->validate(['date'=>'nullable|date_format:Y-m-d','status'=>['nullable',Rule::in(array_keys(BookingService::STATUSES))],'service_id'=>'nullable|integer','staff_id'=>'nullable|integer','search'=>'nullable|string|max:100','calendar'=>'nullable|in:day,week,month']);
        $base=Booking::where('business_id',$r->user()->business_id)->with(['customer','staff','resource']);
        $q=(clone $base)->when($d['status']??null,fn($q,$v)=>$q->where('status',$v))->when($d['service_id']??null,fn($q,$v)=>$q->where('service_id',$v))->when($d['staff_id']??null,fn($q,$v)=>$q->where('staff_id',$v))->when($d['search']??null,fn($q,$v)=>$q->where(fn($q)=>$q->where('code','like','%'.$v.'%')->orWhere('customer_name','like','%'.$v.'%')->orWhereHas('customer',fn($q)=>$q->where('name','like','%'.$v.'%'))));
        $date=\Carbon\CarbonImmutable::parse($d['date']??now()->toDateString());$mode=$d['calendar']??'week';$start=match($mode){'month'=>$date->startOfMonth(),'week'=>$date->startOfWeek(),default=>$date->startOfDay()};$end=match($mode){'month'=>$date->endOfMonth(),'week'=>$date->endOfWeek(),default=>$date->endOfDay()};
        $calendar=(clone $q)->whereBetween('starts_at',[$start,$end])->orderBy('starts_at')->limit(500)->get();
        $stats=[];foreach(['Hari ini'=>[now()->startOfDay(),now()->endOfDay()],'Minggu ini'=>[now()->startOfWeek(),now()->endOfWeek()],'Bulan ini'=>[now()->startOfMonth(),now()->endOfMonth()],'Tahun ini'=>[now()->startOfYear(),now()->endOfYear()]] as $label=>$range)$stats[$label]=(clone $base)->whereBetween('starts_at',$range)->count();
        return view('premium.bookings',['bookings'=>$q->when($d['date']??null,fn($q,$v)=>$q->whereDate('starts_at',$v))->orderBy('starts_at')->paginate(20)->withQueryString(),'editing'=>$booking??new Booking,'services'=>BusinessService::where('kind','appointment')->where('is_active',true)->get(),'customers'=>Customer::orderBy('name')->get(),'staff'=>User::where('is_active',true)->get(),'resources'=>BookingResource::where('is_active',true)->get(),'tables'=>Table::get(),'statuses'=>BookingService::STATUSES,'stats'=>$stats,'calendarBookings'=>$calendar,'calendarStart'=>$start,'calendarEnd'=>$end,'settings'=>app(ReservationSchedule::class)->settings($r->user()->business),'schedules'=>BookingStaffSchedule::with('business')->get()]);
    }
    private function data(Request $r):array{return $r->validate(['customer_id'=>'required|integer','service_id'=>'required|integer','staff_id'=>'nullable|integer','resource_id'=>'nullable|integer','capacity_units'=>'nullable|integer|min:1|max:1000','booking_date'=>'required|date_format:Y-m-d','start_time'=>'required|date_format:H:i','notes'=>'nullable|string|max:2000']);}
    public function store(Request $r,BookingService $s){$s->save($r->user(),$this->data($r));return redirect()->route('bookings.index')->with('success','Reservasi dibuat.');}
    public function update(Request $r,Booking $booking,BookingService $s){\Illuminate\Support\Facades\Gate::authorize('update',$booking);$s->save($r->user(),$this->data($r),$booking->id);return redirect()->route('bookings.index')->with('success','Jadwal diperbarui.');}
    public function status(Request $r,Booking $booking,BookingService $s){$d=$r->validate(['status'=>['required',Rule::in(array_keys(BookingService::STATUSES))]]);$s->status($r->user(),$booking->id,$d['status']);return back()->with('success','Status reservasi diperbarui.');}
    public function show(Request $r,Booking $booking){abort_unless((int)$booking->business_id===(int)$r->user()->business_id,404);$booking->load(['customer','staff','resource','payments']);return view('premium.booking-detail',['booking'=>$booking,'statuses'=>BookingService::STATUSES]);}
    public function receipt(Request $r,Booking $booking){
        abort_unless((int)$booking->business_id===(int)$r->user()->business_id,404);
        \Illuminate\Support\Facades\Gate::authorize('view',$booking);
        $d=$r->validate(['width'=>'nullable|in:58,80']);
        $booking->load(['customer','staff','resource','payments']);
        return response()->view('premium.booking-receipt',['booking'=>$booking,'business'=>$r->user()->business,'statuses'=>BookingService::STATUSES,'width'=>$d['width']??'80'])->header('Cache-Control','private, no-store');
    }
    public function service(Request $r){$d=$r->validate(['name'=>'required|string|max:150','price'=>'required|numeric|min:0|max:100000000','duration_minutes'=>'required|integer|min:5|max:720','booking_category'=>'nullable|string|max:100','booking_capacity'=>'nullable|integer|min:1|max:1000','buffer_minutes'=>'nullable|integer|min:0|max:240']);BusinessService::create($d+['kind'=>'appointment','unit'=>'session']);return back()->with('success','Layanan dibuat.');}
    public function settings(Request $r){
        $d=$r->validate(['enabled'=>'required|boolean','auto_confirm'=>'required|boolean','opens_at'=>'required|date_format:H:i','closes_at'=>'required|date_format:H:i|after:opens_at','days'=>'required|array|min:1','days.*'=>'integer|between:0,6|distinct','holidays'=>'nullable|string|max:3000','slot_minutes'=>'required|integer|min:5|max:120','payment_mode'=>'required|in:free,deposit,full','deposit_percent'=>'required|integer|min:1|max:100']);
        $d['days']=array_map('intval',$d['days']);$d['holidays']=array_values(array_filter(array_map('trim',explode(',',$d['holidays']??''))));foreach($d['holidays'] as $date)if(!preg_match('/^\d{4}-\d{2}-\d{2}$/',$date) || !\Carbon\Carbon::hasFormat($date,'Y-m-d'))throw \Illuminate\Validation\ValidationException::withMessages(['holidays'=>'Hari libur harus berupa tanggal YYYY-MM-DD, dipisahkan koma.']);
        Setting::setValue('reservation_configuration',json_encode($d));return back()->with('success','Pengaturan reservasi disimpan.');
    }
    public function resource(Request $r){$d=$r->validate(['name'=>'required|string|max:150','kind'=>'required|in:table,court,room,chair,facility','table_id'=>['nullable',Rule::exists('tables','id')->where('business_id',$r->user()->business_id)],'capacity'=>'required|integer|min:1|max:1000']);if(!empty($d['table_id'])){$d['kind']='table';if(BookingResource::where('table_id',$d['table_id'])->exists())throw \Illuminate\Validation\ValidationException::withMessages(['table_id'=>'Meja sudah terdaftar sebagai resource.']);}BookingResource::create($d);return back()->with('success','Fasilitas ditambahkan.');}
    public function schedule(Request $r){$d=$r->validate(['staff_id'=>['required',Rule::exists('users','id')->where('business_id',$r->user()->business_id)],'day_of_week'=>'required|integer|between:0,6','opens_at'=>'required|date_format:H:i','closes_at'=>'required|date_format:H:i|after:opens_at']);BookingStaffSchedule::updateOrCreate(['staff_id'=>$d['staff_id'],'day_of_week'=>$d['day_of_week']],$d);return back()->with('success','Jadwal karyawan disimpan.');}
    public function pay(Request $r,Booking $booking,ReservationPayments $s){$d=$r->validate(['amount'=>'required|numeric|min:0.01|max:100000000','request_key'=>'required|uuid']);$s->cash($r->user(),$booking->id,$d['request_key'],(float)$d['amount']);return back()->with('success','Pembayaran Cash dicatat.');}
    public function link(Request $r,Booking $booking,ReservationPayments $s){$d=$r->validate(['sale_id'=>'required|integer']);$s->link($r->user(),$booking->id,$d['sale_id']);return back()->with('success','Reservasi terhubung dengan transaksi POS.');}
    public function checkout(Request $r,Booking $booking,ReservationPayments $s){$d=$r->validate(['request_key'=>'required|uuid','cash_received'=>'required|numeric|min:0|max:100000000']);$s->checkout($r->user(),$booking->id,$d['request_key'],(float)$d['cash_received']);return back()->with('success','Checkout Cash selesai dan transaksi POS dibuat.');}
    public function serviceUpdate(Request $r,BusinessService $service){abort_unless((int)$service->business_id===(int)$r->user()->business_id && $service->kind==='appointment',404);$d=$r->validate(['name'=>'required|string|max:150','price'=>'required|numeric|min:0|max:100000000','duration_minutes'=>'required|integer|min:5|max:720','booking_category'=>'nullable|string|max:100','booking_capacity'=>'required|integer|min:1|max:1000','buffer_minutes'=>'required|integer|min:0|max:240','is_active'=>'required|boolean']);$service->update($d);return back()->with('success','Layanan diperbarui.');}
    public function resourceUpdate(Request $r,BookingResource $resource){abort_unless((int)$resource->business_id===(int)$r->user()->business_id,404);$d=$r->validate(['name'=>'required|string|max:150','capacity'=>'required|integer|min:1|max:1000','is_active'=>'required|boolean']);$resource->update($d);return back()->with('success','Fasilitas diperbarui.');}
    public function report(Request $r){
        $d=$r->validate(['from'=>'required|date_format:Y-m-d','to'=>'required|date_format:Y-m-d|after_or_equal:from']);
        $query=Booking::where('business_id',$r->user()->business_id)->whereBetween('starts_at',[$d['from'].' 00:00:00',$d['to'].' 23:59:59'])->orderBy('id');
        return response()->streamDownload(function()use($query){$out=fopen('php://output','w');fputcsv($out,['Kode','Pelanggan','Layanan','Jadwal','Status','Total','Dibayar','Sisa']);foreach($query->cursor() as $b){$values=[$b->code??'Booking #'.$b->id,$b->customer_name??$b->customer?->name,$b->service_name,$b->starts_at->format('Y-m-d H:i'),$b->status,$b->total,$b->paid,max(0,$b->total-$b->paid)];fputcsv($out,array_map(fn($v)=>preg_match('/^[=+@\-\t\r]/',(string)$v)?"'".$v:$v,$values));}fclose($out);},'reservasi.csv',['Content-Type'=>'text/csv']);
    }
}
